// Response types come from the daemon's OpenAPI schema (schema.d.ts, generated by `npm run api`).
// Event payloads travel over Server-Sent Events, which OpenAPI doesn't describe, so they are
// written here to match src/assistant/core/events.py and the bus events in src/assistant/daemon/runs.py.
import type { components } from "./schema";

type Schemas = components["schemas"];

/** The conversation this page is on, and how its messages are labeled. */
export type Session = { channel: string; thread_id: string };
export type Conversation = Schemas["Conversation"];
export type ShownMessage = Schemas["ShownMessage"];
export type Job = Schemas["Job"];
export type RunRecord = Schemas["RunRecord"];
export type TelegramStatus = Schemas["TelegramStatus"];
export type SlackStatus = Schemas["SlackStatus"];
export type SlackTokens = Schemas["SlackTokens"];
export type SpeechStatus = Schemas["SpeechStatus"];
export type EmailAccount = Schemas["EmailAccount"];
export type EmailSettings = Schemas["EmailSettings"];
export type EmailProvider = Schemas["EmailProvider"];
export type ModelStatus = Schemas["ModelStatus"];
export type ModelProvider = Schemas["ModelProvider"];
export type ModelChange = Schemas["ModelChange"];
export type Device = Schemas["Device"];
export type PairingCode = Schemas["PairingCode"];
export type Me = Schemas["Me"];
export type SkillSummary = Schemas["SkillSummary"];
export type Skill = Schemas["Skill"];
export type FoundSkill = Schemas["FoundSkill"];
export type FoundServer = Schemas["FoundServer"];
export type ServerField = Schemas["ServerField"];
export type ServerValues = Schemas["ServerValuesBody"];
export type RepositoryContents = Schemas["RepositoryContents"];
export type InstalledFromRepository = Schemas["InstalledFromRepository"];
export type UsageReport = Schemas["UsageReport"];
export type ToolUsage = Schemas["ToolUsage"];
export type TokenReport = Schemas["TokenReport"];
export type TokenRow = Schemas["TokenRow"];
export type StartupStatus = Schemas["StartupStatus"];
export type ConnectedClient = Schemas["ConnectedClient"];
export type McpServerStatus = Schemas["McpServerStatus"];
export type McpToolInfo = Schemas["McpToolInfo"];
export type McpServerSettings = Schemas["McpServerSettings"];
export type McpServerChange = Schemas["McpServerChange"];

export type ApprovalRequest = { tool?: string; reason?: string; command?: string } & Record<string, unknown>;
export type ApprovalRequired = { type: "ApprovalRequired"; interrupt_id: string; request: ApprovalRequest };
export type Decision = { approved: boolean; reason: string | null };

export type RunEvent =
  | { type: "TextDelta"; text: string }
  | { type: "ToolStarted"; name: string; args: Record<string, unknown> }
  | { type: "ToolFinished"; name: string; output: string }
  | ApprovalRequired
  | { type: "Transcribed"; text: string; language: string }
  | { type: "Done" }
  | { type: "Error"; message: string }
  | { type: "Cancelled" };

/** A `run` bus event: a run started by any client or channel. `client_id` is empty for a channel
 * without a client (Telegram). */
export type RunAnnounced = { run_id: string; thread_id: string; channel: string; client_id: string; text: string };

/** A `run_finished` bus event. */
export type RunFinished = { run_id: string; thread_id: string; channel: string; status: string; reply: string };

export type BusEvent = { kind: string; data: Record<string, unknown> };

/** A `job` bus event: a scheduled job finished a run. */
export type JobFinished = { name: string; status: string; summary: string };
